// Worker entry (wrangler `main`). Wraps the OpenNext worker to add a
// scheduled() handler (QA F6): every 15 minutes it asks the app to cancel
// pending_payment orders past settings.orders.paymentWindowMinutes. The app
// route does the R2 work so it runs with the normal OpenNext context.
// Requires the CRON_SECRET secret; without it the route answers 404 and the
// lazy expiry on admin/tracking reads remains the only sweep.
// See https://opennext.js.org/cloudflare/howtos/custom-worker
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

export default {
  fetch: handler.fetch,
  async scheduled(_event, env, ctx) {
    if (!env.CRON_SECRET) return;
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch('https://nowhenceclothings.com/api/admin/orders/expire', {
        method: 'POST',
        headers: { 'x-cron-secret': env.CRON_SECRET },
      }).then(
        async (r) => console.log('cron expire-orders', r.status, await r.text()),
        (err) => console.error('cron expire-orders failed', err && err.message),
      ),
    );
  },
};
